code='''def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    bands = []
    for r in (0, h - 1):
        for color in set(grid[r]) - {bg}:
            cols = [c for c, value in enumerate(grid[r]) if value == color]
            if len(cols) >= 2 and cols == list(range(cols[0], cols[-1] + 1)):
                bands.append((r, color, cols[0], cols[-1]))
    top = next((b for b in bands if b[0] == 0), None)
    bottom = next((b for b in bands if b[0] == h - 1), None)
    if top is None or bottom is None:
        return out
    edge_colors = {top[1], bottom[1]}
    markers = [(r, c, grid[r][c]) for r in range(1, h - 1) for c in range(w)
               if grid[r][c] != bg and grid[r][c] not in edge_colors]
    if not markers:
        return out
    marker_color = Counter(v for _, _, v in markers).most_common(1)[0][0]
    def distance_to_band(band):
        return sum(0 if band[2] <= c <= band[3] else min(abs(c-band[2]), abs(c-band[3])) for _, c, v in markers if v == marker_color)
    source, other = (bottom, top) if distance_to_band(bottom) <= distance_to_band(top) else (top, bottom)
    offsets = {c - source[2] for _, c, v in markers if v == marker_color and source[2] <= c <= source[3]}
    if not offsets:
        offsets = {max(0, min(source[3] - source[2], c - source[2])) for _, c, v in markers if v == marker_color}
    for r, c, v in markers:
        if v != marker_color:
            continue
        # Each point sends a ray toward the opposite horizontal boundary.
        for rr in range(r + 1, h):
            if grid[rr][c] != bg:
                break
            out[rr][c] = marker_color
        out[r][c] = 4
    # The boundary band opposite the source casts corresponding parallel rays.
    for offset in offsets:
        c = other[2] + offset
        if not other[2] <= c <= other[3]:
            continue
        for rr in range(other[0] + 1, h):
            out[rr][c] = marker_color
    return out
